namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public string Instructor { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public string Schedule { get; set; } = string.Empty;
    public string Semester { get; set; } = string.Empty;
    public int MaxEnrollment { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{5,12}$", ErrorMessage = "Student ID must be 5–12 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    [StringLength(500, ErrorMessage = "Comments cannot exceed 500 characters.")]
    public string? Comments { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    IReadOnlyList<Course> GetCoursesByDepartment(int departmentId);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS",   Name = "Computer Science",    Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics",         Description = "Pure and applied mathematics including statistics." },
            new() { Id = 3, Code = "PHYS", Name = "Physics",             Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG",  Name = "English",             Description = "Literature, writing, and language studies." },
            new() { Id = 5, Code = "HIST", Name = "History",             Description = "Study of past events and civilizations." },
            new() { Id = 6, Code = "BIOL", Name = "Biology",             Description = "Study of living organisms and life processes." },
        ];

        _courses =
        [
            // Computer Science
            new() { Id = 1,  CourseCode = "CS 101",   Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering fundamental concepts including problem solving, abstraction, algorithms, and data representation. Students will learn to write programs in Python and explore how computing impacts society.", Credits = 3, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = "Dr. Alice Chen",       InstructorBio = "Dr. Chen holds a Ph.D. from MIT and has 15 years of experience teaching introductory CS. Her research focuses on CS education and curriculum design.",                  Schedule = "Mon/Wed/Fri 9:00–9:50 AM",  Semester = "Fall 2026",   MaxEnrollment = 120, IsFeatured = true },
            new() { Id = 2,  CourseCode = "CS 201",   Title = "Data Structures & Algorithms",     Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes Big-O analysis and problem-solving strategies.", Credits = 4, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = "Dr. Bob Martinez",     InstructorBio = "Dr. Martinez is a leading researcher in algorithm optimization with publications in ACM and IEEE journals. He has been teaching at the university for 10 years.",        Schedule = "Tue/Thu 10:30–11:45 AM",     Semester = "Fall 2026",   MaxEnrollment = 80,  IsFeatured = true },
            new() { Id = 3,  CourseCode = "CS 310",   Title = "Database Systems",                 Description = "Relational database design, SQL, normalization, indexing, and transaction management. Includes an introduction to NoSQL databases and modern data storage paradigms.",                                                                         Credits = 3, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = "Prof. Carol Nguyen",   InstructorBio = "Prof. Nguyen spent 12 years in industry at Oracle and Amazon before joining academia. She specializes in distributed database systems.",                                  Schedule = "Mon/Wed 2:00–3:15 PM",       Semester = "Fall 2026",   MaxEnrollment = 60,  IsFeatured = false },
            new() { Id = 4,  CourseCode = "CS 450",   Title = "Machine Learning",                 Description = "Introduction to machine learning covering supervised and unsupervised learning, neural networks, and model evaluation. Hands-on projects using Python and popular ML frameworks.",                                                              Credits = 3, DepartmentId = 1, DepartmentName = "Computer Science", Instructor = "Dr. Alice Chen",       InstructorBio = "Dr. Chen holds a Ph.D. from MIT and has 15 years of experience teaching introductory CS. Her research focuses on CS education and curriculum design.",                  Schedule = "Tue/Thu 1:00–2:15 PM",       Semester = "Spring 2027", MaxEnrollment = 50,  IsFeatured = true },

            // Mathematics
            new() { Id = 5,  CourseCode = "MATH 101", Title = "Calculus I",                       Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",                                                                                                             Credits = 4, DepartmentId = 2, DepartmentName = "Mathematics",      Instructor = "Dr. David Kim",        InstructorBio = "Dr. Kim is an award-winning educator who has authored three widely-used calculus textbooks. He received the university's Distinguished Teaching Award in 2024.",        Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Semester = "Fall 2026",   MaxEnrollment = 150, IsFeatured = true },
            new() { Id = 6,  CourseCode = "MATH 201", Title = "Linear Algebra",                   Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Applications in data science and engineering.",                                                                                                                  Credits = 3, DepartmentId = 2, DepartmentName = "Mathematics",      Instructor = "Dr. Emily Park",       InstructorBio = "Dr. Park's research in applied linear algebra has been funded by NSF grants. She brings real-world applications into the classroom.",                                    Schedule = "Tue/Thu 9:00–10:15 AM",      Semester = "Fall 2026",   MaxEnrollment = 80,  IsFeatured = false },
            new() { Id = 7,  CourseCode = "MATH 301", Title = "Probability & Statistics",         Description = "Probability theory, random variables, distributions, hypothesis testing, confidence intervals, and regression analysis.",                                                                                                                        Credits = 3, DepartmentId = 2, DepartmentName = "Mathematics",      Instructor = "Dr. David Kim",        InstructorBio = "Dr. Kim is an award-winning educator who has authored three widely-used calculus textbooks. He received the university's Distinguished Teaching Award in 2024.",        Schedule = "Mon/Wed 11:00 AM–12:15 PM",  Semester = "Spring 2027", MaxEnrollment = 70,  IsFeatured = false },

            // Physics
            new() { Id = 8,  CourseCode = "PHYS 101", Title = "General Physics I",                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments and data analysis.",                                                                                                                                Credits = 4, DepartmentId = 3, DepartmentName = "Physics",          Instructor = "Dr. Frank Wilson",     InstructorBio = "Dr. Wilson is a former NASA researcher whose work on fluid dynamics in microgravity has been published in Nature Physics.",                                              Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Semester = "Fall 2026",   MaxEnrollment = 100, IsFeatured = false },
            new() { Id = 9,  CourseCode = "PHYS 201", Title = "Electromagnetism",                 Description = "Electric fields, magnetic fields, Maxwell's equations, electromagnetic waves, and optics.",                                                                                                                                                     Credits = 4, DepartmentId = 3, DepartmentName = "Physics",          Instructor = "Dr. Grace Liu",        InstructorBio = "Dr. Liu specializes in photonics and has 20+ publications in peer-reviewed journals. She is passionate about making physics accessible and engaging.",                  Schedule = "Tue/Thu 2:00–3:15 PM",       Semester = "Spring 2027", MaxEnrollment = 60,  IsFeatured = false },

            // English
            new() { Id = 10, CourseCode = "ENG 101",  Title = "College Composition",              Description = "Develops critical reading and academic writing skills. Students produce essays in multiple genres while learning argumentation, research methods, and citation practices.",                                                                        Credits = 3, DepartmentId = 4, DepartmentName = "English",          Instructor = "Prof. Hannah Brooks",  InstructorBio = "Prof. Brooks is a published author and writing workshop leader. She believes every student can become a confident, effective writer.",                                   Schedule = "Mon/Wed/Fri 1:00–1:50 PM",   Semester = "Fall 2026",   MaxEnrollment = 30,  IsFeatured = false },
            new() { Id = 11, CourseCode = "ENG 250",  Title = "American Literature",              Description = "Survey of American literature from the colonial period to the present, examining major authors, movements, and cultural contexts.",                                                                                                              Credits = 3, DepartmentId = 4, DepartmentName = "English",          Instructor = "Dr. Ian Crawford",     InstructorBio = "Dr. Crawford is a Fulbright scholar specializing in 20th-century American fiction. His recent book explores the intersection of literature and social justice.",         Schedule = "Tue/Thu 11:00 AM–12:15 PM",  Semester = "Fall 2026",   MaxEnrollment = 35,  IsFeatured = false },

            // History
            new() { Id = 12, CourseCode = "HIST 101", Title = "World History to 1500",            Description = "Survey of world civilizations from prehistory through the late medieval period, covering major cultures, empires, and transformative events.",                                                                                                    Credits = 3, DepartmentId = 5, DepartmentName = "History",          Instructor = "Dr. Julia Romano",     InstructorBio = "Dr. Romano is an archaeologist and historian whose fieldwork in the Mediterranean has reshaped our understanding of ancient trade networks.",                          Schedule = "Mon/Wed 3:30–4:45 PM",       Semester = "Fall 2026",   MaxEnrollment = 90,  IsFeatured = false },
            new() { Id = 13, CourseCode = "HIST 220", Title = "Modern European History",          Description = "Europe from the Enlightenment to the present day, examining revolutions, industrialization, world wars, and the formation of the European Union.",                                                                                               Credits = 3, DepartmentId = 5, DepartmentName = "History",          Instructor = "Dr. Julia Romano",     InstructorBio = "Dr. Romano is an archaeologist and historian whose fieldwork in the Mediterranean has reshaped our understanding of ancient trade networks.",                          Schedule = "Tue/Thu 3:30–4:45 PM",       Semester = "Spring 2027", MaxEnrollment = 60,  IsFeatured = false },

            // Biology
            new() { Id = 14, CourseCode = "BIOL 101", Title = "Introduction to Biology",         Description = "Fundamental principles of biology including cell structure, genetics, evolution, and ecology. Includes weekly lab sessions.",                                                                                                                     Credits = 4, DepartmentId = 6, DepartmentName = "Biology",          Instructor = "Dr. Karen Patel",      InstructorBio = "Dr. Patel is a molecular biologist with a passion for teaching. Her lab has published groundbreaking work on gene editing techniques.",                                 Schedule = "Mon/Wed/Fri 8:00–8:50 AM",   Semester = "Fall 2026",   MaxEnrollment = 100, IsFeatured = true },
            new() { Id = 15, CourseCode = "BIOL 305", Title = "Genetics & Genomics",             Description = "Mendelian genetics, molecular genetics, genomic analysis, and bioinformatics. Explores the ethical implications of genetic technologies.",                                                                                                        Credits = 3, DepartmentId = 6, DepartmentName = "Biology",          Instructor = "Dr. Karen Patel",      InstructorBio = "Dr. Patel is a molecular biologist with a passion for teaching. Her lab has published groundbreaking work on gene editing techniques.",                                 Schedule = "Tue/Thu 10:30–11:45 AM",     Semester = "Spring 2027", MaxEnrollment = 40,  IsFeatured = false },
        ];
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.Find(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        IEnumerable<Course> results = _courses;

        if (departmentId.HasValue)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            results = results.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return results.OrderBy(c => c.CourseCode).ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.Find(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).OrderBy(c => c.CourseCode).ToList();
}

