@page "/courses"
@inject ICatalogService CatalogService

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Search by title, code, instructor…" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th>Semester</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.CourseCode</td>
                    <td>@course.Title</td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.Instructor</td>
                    <td>@course.Semester</td>
                    <td><a href="courses/@course.Id" class="btn btn-outline-primary btn-sm">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course.</p>

<div class="row">
    <div class="col-md-8">
        <EditForm Model="Model" method="post" FormName="enroll" OnValidSubmit="HandleSubmit">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
                <ValidationMessage For="() => Model.StudentName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. STU12345" />
                <ValidationMessage For="() => Model.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in CatalogService.GetCourses())
                    {
                        <option value="@course.Id">@course.CourseCode — @course.Title (@course.Semester)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="comments" class="form-label">Comments (optional)</label>
                <InputTextArea id="comments" @bind-Value="Model.Comments" class="form-control" rows="3" />
                <ValidationMessage For="() => Model.Comments" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        // In a real app this would persist to a database.
        // For now we redirect to a confirmation page.
        NavigationManager.NavigateTo(
            $"enroll/confirmation?name={Uri.EscapeDataString(Model.StudentName)}&courseId={Model.CourseId}");
    }

    [Inject] private NavigationManager NavigationManager { get; set; } = default!;
}

@page "/enroll/confirmation"
@inject ICatalogService CatalogService

<PageTitle>Enrollment Submitted — University Course Catalog</PageTitle>

<div class="text-center mt-5">
    <h1 class="text-success">✅ Enrollment Request Submitted</h1>

    <p class="lead mt-3">
        Thank you, <strong>@Name</strong>! Your enrollment request
        @if (SelectedCourse is not null)
        {
            <text> for <strong>@SelectedCourse.CourseCode — @SelectedCourse.Title</strong></text>
        }
        has been received.
    </p>

    <p>You will receive a confirmation via your university email once your request is processed.</p>

    <div class="mt-4">
        <a href="courses" class="btn btn-primary me-2">Browse More Courses</a>
        <a href="enroll" class="btn btn-outline-secondary">Submit Another Request</a>
    </div>
</div>

@code {
    [SupplyParameterFromQuery] public string? Name { get; set; }
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private Course? SelectedCourse { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue)
            SelectedCourse = CatalogService.GetCourse(CourseId.Value);
    }
}

